  <script>
    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB);
    let isNight = false;

    // Camera setup
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(40, 30, 40);

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 20;
    controls.maxDistance = 100;

    // Lights
    const ambientLight = new THREE.AmbientLight(0xFFFFFF, 0.6);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xFFFFFF, 0.8);
    directionalLight.position.set(50, 100, 50);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    scene.add(directionalLight);

    // Helper function to create a voxel
    function createVoxel(x, y, z, color, opacity = 1) {
      const geometry = new THREE.BoxGeometry(1, 1, 1);
      const material = new THREE.MeshLambertMaterial({ color: color, transparent: opacity < 1, opacity: opacity });
      const voxel = new THREE.Mesh(geometry, material);
      voxel.position.set(x, y, z);
      voxel.castShadow = true;
      voxel.receiveShadow = true;
      scene.add(voxel);
      return voxel;
    }

    // Create ground/base
    for (let x = -35; x <= 35; x++) {
      for (let z = -35; z <= 35; z++) {
        // Grass with some variation
        const distFromCenter = Math.sqrt(x*x + z*z);
        if (distFromCenter <= 35) {
          const greenVariation = Math.random() * 0.1;
          const green = new THREE.Color(0.2 + greenVariation, 0.6 + greenVariation, 0.2);
          createVoxel(x, -0.5, z, green);
        }
      }
    }

    // Create water
    function createWater(centerX, centerZ, radius) {
      for (let x = centerX - radius; x <= centerX + radius; x++) {
        for (let z = centerZ - radius; z <= centerZ + radius; z++) {
          const distFromCenter = Math.sqrt(Math.pow(x - centerX, 2) + Math.pow(z - centerZ, 2));
          if (distFromCenter < radius) {
            // Water ripple effect
            const ripple = Math.sin(distFromCenter * 2) * 0.1;
            const waterColor = new THREE.Color(0.2, 0.4 + ripple, 0.8 + ripple);
            createVoxel(x, -0.3, z, waterColor, 0.8);
          }
        }
      }
    }

    // Create a small pond
    createWater(-15, -10, 8);

    // Create stone path
    function createPath(startX, startZ, endX, endZ, width) {
      const length = Math.max(Math.abs(endX - startX), Math.abs(endZ - startZ));
      for (let i = 0; i <= length; i++) {
        const t = i / length;
        const x = Math.floor(startX + (endX - startX) * t);
        const z = Math.floor(startZ + (endZ - startZ) * t);

        for (let w = -width; w <= width; w++) {
          if (Math.abs(endX - startX) > Math.abs(endZ - startZ)) {
            // Horizontal path
            const stoneColor = 0x808080 + Math.floor(Math.random() * 0x0F0F0F);
            createVoxel(x, -0.4, z + w, stoneColor);
          } else {
            // Vertical path
            const stoneColor = 0x808080 + Math.floor(Math.random() * 0x0F0F0F);
            createVoxel(x + w, -0.4, z, stoneColor);
          }
        }
      }
    }

    // Create paths
    createPath(-30, 0, 0, 0, 1);  // Main path to pagoda
    createPath(-15, -20, -15, 0, 1);  // Path to pond
    createPath(-15, 0, -15, 15, 1);   // Path to cherry blossoms

    // Function to create a cherry blossom tree
    function createCherryBlossomTree(baseX, baseY, baseZ, size = 1) {
      // Trunk
      const trunkHeight = 3 + Math.floor(Math.random() * 3);
      for (let y = 0; y < trunkHeight; y++) {
        createVoxel(baseX, baseY + y, baseZ, 0x8B4513);
        if (size > 1 && y < 2) {
          createVoxel(baseX + 1, baseY + y, baseZ, 0x8B4513);
          createVoxel(baseX, baseY + y, baseZ + 1, 0x8B4513);
          createVoxel(baseX - 1, baseY + y, baseZ, 0x8B4513);
          createVoxel(baseX, baseY + y, baseZ - 1, 0x8B4513);
        }
      }

      // Blossom foliage
