                color = 0xFFC0CB; // Pink
              } else {
                color = 0xFFFAFA; // White
              }
              createVoxel(baseX + x, baseY + trunkHeight - 1 + y, baseZ + z, color);
            }
          }
        }
      }
    }

    // Function to create a regular tree
    function createTree(baseX, baseY, baseZ, type = 'normal', size = 1) {
      // Trunk
      const trunkHeight = 3 + Math.floor(Math.random() * 3);
      for (let y = 0; y < trunkHeight; y++) {
