      }

      if (type === 'pine') {
        // Conical shape for pine trees
        for (let y = 0; y <= foliageRadius * 2; y++) {
          const levelRadius = foliageRadius - (y / 2);
          if (levelRadius > 0) {
            for (let x = -levelRadius; x <= levelRadius; x++) {
              for (let z = -levelRadius; z <= levelRadius; z++) {
                const distance = Math.sqrt(x*x + z*z);
                if (distance <= levelRadius && Math.random() > 0.3) {
                  createVoxel(baseX + x, baseY + trunkHeight + y, baseZ + z, foliageColor);
                }
              }
            }
          }
        }
      } else if (type === 'bamboo') {
        // Bamboo style
        for (let y = 0; y < 10; y++) {
          createVoxel(baseX, baseY + trunkHeight + y, baseZ, 0x90EE90);
          if (y > 3 && y % 2 === 0) {
            for (let x = -1; x <= 1; x++) {
              for (let z = -1; z <= 1; z++) {
                if ((x !== 0 || z !== 0) && Math.random() > 0.5) {
                  createVoxel(baseX + x, baseY + trunkHeight + y, baseZ + z, 0x90EE90);
                }
              }
            }
          }
        }
      } else {
        // Round foliage for normal and maple trees
        for (let x = -foliageRadius; x <= foliageRadius; x++) {
          for (let y = 0; y <= foliageRadius; y++) {
            for (let z = -foliageRadius; z <= foliageRadius; z++) {
              const distance = Math.sqrt(x*x + y*y + z*z);
              if (distance <= foliageRadius && Math.random() > 0.3) {
                // Add some variation to the color
                const colorVariation = Math.random() * 0.1;
                const finalColor = new THREE.Color(foliageColor).offsetHSL(0, 0, colorVariation);
                createVoxel(baseX + x, baseY + trunkHeight + y, baseZ + z, finalColor);
              }
            }
          }
        }
      }
    }

    // Create pagoda
    function createPagoda(baseX, baseY, baseZ) {
      const pagodaWidth = 9;
      const levels = 5;
      const baseColors = [0x8B0000, 0xA52A2A, 0x8B4513, 0xCD5C5C, 0xB22222];
      const roofColor = 0xCD5C5C;

      // Base platform
      for (let x = -pagodaWidth - 2; x <= pagodaWidth + 2; x++) {
        for (let z = -pagodaWidth - 2; z <= pagodaWidth + 2; z++) {
          createVoxel(baseX + x, baseY - 1, baseZ + z, 0x696969);
        }
      }

      for (let level = 0; level < levels; level++) {
        const currentWidth = pagodaWidth - (level * 2);
        const currentY = baseY + level * 5;
        const color = baseColors[level % baseColors.length];

        // Floor
        for (let x = -currentWidth; x <= currentWidth; x++) {
          for (let z = -currentWidth; z <= currentWidth; z++) {
            createVoxel(baseX + x, currentY, baseZ + z, color);
          }
        }

        // Walls
        if (level < levels - 1) {
          for (let x = -currentWidth; x <= currentWidth; x++) {
            for (let y = 1; y <= 3; y++) {
